/** @typedef {{ modeCode: number; model: number; seriesName: string; tab: number; name: string; gears: number[][] }} XproScene */
/** @typedef {{ key: string; maxWatts: number; limitWatts: number; scenes: XproScene[]; customLinks: { R: number[][]; W: number[][]; G: number[][]; B: number[][] } }} XproProfile */
/** @typedef {{ enable: number; dayList: number[]; startH: number; startM: number; endH: number; endM: number; modeCode: number; gear: number; red: number; green: number; white: number; blue: number; fan: number; pwm: number[]; powerWatts: number; name: string; seriesName?: string; hasSunrise?: boolean; hasSunset?: boolean; sunriseDays?: number[]; sunsetDays?: number[] }} XproTrip */

export const SCENE_META = FACTORY_DATA.sceneMeta;
export const CULTIVATION_PRESETS = FACTORY_DATA.cultivationPresets;
export const DEFAULT_XPRO_MODEL = 'SG-X-PRO-60';

const MODEL_KEYS = Object.keys(FACTORY_DATA.modelTables);

/**
 * Clamp and round an integer safely, returning `fallback` when non-numeric.
 * @param {unknown} value
 * @param {number} min
 * @param {number} max
 * @param {number} [fallback]
 * @returns {number}
 */
function clampNum(value, min, max, fallback = min) {
  const n = Number(value);
  if (!Number.isFinite(n)) return fallback;
  return Math.max(min, Math.min(max, Math.round(n)));
}

/**
 * Resolve factory profile for any SG-X-PRO model/advertisement name (30/40/60/80/100/120/150).
 * @param {unknown} modelOrDeviceName
 * @returns {XproProfile}
 */
export function resolveXproProfile(modelOrDeviceName) {
  const raw = String(modelOrDeviceName ?? '').trim().toUpperCase();
  let matchedKey = DEFAULT_XPRO_MODEL;
  if (raw) {
    const numMatch = raw.match(/SG-X-PRO-(\d{2,3})/) || raw.match(/X-PRO-(\d{2,3})/);
    if (numMatch) {
      const candidate = `SG-X-PRO-${numMatch[1]}`;
      if (FACTORY_DATA.modelTables[candidate]) {
        matchedKey = candidate;
      }
    } else {
      for (const k of MODEL_KEYS) {
        if (raw.includes(k)) {
          matchedKey = k;
          break;
        }
      }
    }
  }
  const table = FACTORY_DATA.modelTables[matchedKey];
  const scenes = FACTORY_DATA.sceneMeta.map(meta => ({
    ...meta,
    gears: (table.gearsByMode[String(meta.modeCode)] || []).map(g => [...g]),
  }));
  return {
    key: matchedKey,
    maxWatts: table.maxWatts,
    limitWatts: table.limitWatts,
    scenes,
    customLinks: table.customLinks,
  };
}

/**
 * Official Netlea wattage formula (`getCustomPowerValue`):
 * sum channel watts and subtract `(activeChannels - 1)` when multiple channels draw >= 1W.
 * @param {number[]} channelWatts
 * @returns {number}
 */
export function calcCustomPowerWatts(channelWatts) {
  let total = 0;
  let activeCount = 0;
  for (const w of channelWatts) {
    const iw = Math.max(0, Math.round(Number(w) || 0));
    if (iw >= 1) activeCount += 1;
    total += iw;
  }
  if (activeCount > 1) {
    total -= activeCount - 1;
  }
  return Math.max(0, total);
}

/**
 * Convert a 0..100% slider value to a factory link index on the given link table.
 * @param {number[][]} links
 * @param {number} pct
 * @returns {number}
 */
function pctToLinkIndex(links, pct) {
  const maxIdx = Math.max(0, links.length - 1);
  const clamped = clampNum(pct, 0, 100, 0);
  if (clamped <= 0) return 0;
  if (clamped >= 100) return maxIdx;
  return Math.max(0, Math.min(maxIdx, Math.round((clamped / 100) * maxIdx)));
}

/**
 * Convert a hardware PWM byte (0..255) back to 0..100% + per-channel wattage via inverse lookup.
 * @param {number[][]} links
 * @param {number} pwmByte
 * @returns {{ pct: number; watts: number; index: number }}
 */
function pwmToPctAndWatts(links, pwmByte) {
  const pwm = clampNum(pwmByte, 0, 255, 0);
  if (pwm <= 0) {
    return { pct: 0, watts: 0, index: 0 };
  }
  let bestIdx = 0;
  for (let i = 0; i < links.length; i += 1) {
    if (links[i][0] <= pwm) {
      bestIdx = i;
    } else {
      break;
    }
  }
  const maxIdx = Math.max(1, links.length - 1);
  const pct = clampNum(Math.round((bestIdx * 100) / maxIdx), 0, 100, 0);
  return { pct, watts: links[bestIdx][1], index: bestIdx };
}

/**
 * Decode hardware 5-byte PWM `[R, W, G, B, F]` into `%` channels, wattage, and exact scene match.
 * @param {XproProfile} profile
 * @param {number[]} pwmBytes
 */
export function decodeHardwarePwm(profile, pwmBytes) {
  const p = Array.isArray(pwmBytes) ? pwmBytes : [];
  const rPwm = clampNum(p[0], 0, 255, 0);
  const wPwm = clampNum(p[1], 0, 255, 0);
  const gPwm = clampNum(p[2], 0, 255, 0);
  const bPwm = clampNum(p[3], 0, 255, 0);
  const fan = clampNum(p[4], 0, 10, 0);

  const rInfo = pwmToPctAndWatts(profile.customLinks.R, rPwm);
  const wInfo = pwmToPctAndWatts(profile.customLinks.W, wPwm);
  const gInfo = pwmToPctAndWatts(profile.customLinks.G, gPwm);
  const bInfo = pwmToPctAndWatts(profile.customLinks.B, bPwm);

  /** @type {{ modeCode: number; model: number; seriesName: string; tab: number; name: string; gear: number; powerWatts: number } | null} */
  let matchedScene = null;
  for (const sc of profile.scenes) {
    for (let gi = 0; gi < sc.gears.length; gi += 1) {
      const g = sc.gears[gi];
      if (g[0] === rPwm && g[1] === wPwm && g[2] === gPwm && g[3] === bPwm) {
        matchedScene = {
          modeCode: sc.modeCode,
          model: sc.model,
          seriesName: sc.seriesName,
          tab: sc.tab,
          name: sc.name,
          gear: gi + 1,
          powerWatts: g[4],
        };
        break;
      }
    }
    if (matchedScene) break;
  }

  const customWatts = calcCustomPowerWatts([rInfo.watts, wInfo.watts, gInfo.watts, bInfo.watts]);
  const powerWatts = matchedScene ? matchedScene.powerWatts : customWatts;

  return {
    pwm: { red: rPwm, white: wPwm, green: gPwm, blue: bPwm, fan },
    pwmList: [rPwm, wPwm, gPwm, bPwm, fan],
    channels: {
      red: rInfo.pct,
      green: gInfo.pct,
      white: wInfo.pct,
      blue: bInfo.pct,
      fan,
    },
    powerWatts,
    maxWatts: profile.maxWatts,
    matchedScene,
  };
}

/**
 * Encode one of the 12 official scenes (`modeCode` 0..11) + `gear` (1..10, or 1..5 for 月光)
 * into hardware `[R, W, G, B, F]` PWM and decoded percentages.
 * @param {XproProfile} profile
 * @param {number} modeCode
 * @param {number} gear
 * @param {number} [fan]
 */
export function encodeSceneGearPwm(profile, modeCode, gear, fan = 0) {
  const code = clampNum(modeCode, 0, 11, 0);
  const scene = profile.scenes.find(s => s.modeCode === code) || profile.scenes[0];
  const gearCount = Math.max(1, scene.gears.length);
  const safeGear = clampNum(gear, 1, gearCount, Math.min(8, gearCount));
  const row = scene.gears[safeGear - 1];
  const safeFan = clampNum(fan, 0, 10, 0);
  const pwm = [row[0], row[1], row[2], row[3], safeFan];
  const decoded = decodeHardwarePwm(profile, pwm);
  return {
    modeCode: scene.modeCode,
    model: scene.model,
    seriesName: scene.seriesName,
    sceneName: scene.name,
    gear: safeGear,
    maxGear: gearCount,
    pwm,
    channels: decoded.channels,
    powerWatts: row[4],
    maxWatts: profile.maxWatts,
  };
}

/**
 * Encode custom `{ red, green, white, blue, fan }` (0..100%) using factory calibration curves,
 * proportionally scaling down if combined power exceeds `profile.maxWatts`.
 * @param {XproProfile} profile
 * @param {{ red?: unknown; green?: unknown; white?: unknown; blue?: unknown; fan?: unknown }} rawChannels
 * @param {{ clampToMaxPower?: boolean }} [opts]
 */
export function encodeCustomChannelsPwm(profile, rawChannels, opts = {}) {
  const clampToMaxPower = opts.clampToMaxPower !== false;
  const req = {
    red: clampNum(rawChannels?.red, 0, 100, 0),
    green: clampNum(rawChannels?.green, 0, 100, 0),
    white: clampNum(rawChannels?.white, 0, 100, 0),
    blue: clampNum(rawChannels?.blue, 0, 100, 0),
    fan: clampNum(rawChannels?.fan, 0, 5, 0),
  };

  /** @param {{ red: number; green: number; white: number; blue: number; fan: number }} ch */
  const evaluate = (ch) => {
    const ri = pctToLinkIndex(profile.customLinks.R, ch.red);
    const wi = pctToLinkIndex(profile.customLinks.W, ch.white);
    const gi = pctToLinkIndex(profile.customLinks.G, ch.green);
    const bi = pctToLinkIndex(profile.customLinks.B, ch.blue);
    const rl = profile.customLinks.R[ri];
    const wl = profile.customLinks.W[wi];
    const gl = profile.customLinks.G[gi];
    const bl = profile.customLinks.B[bi];
    const powerWatts = calcCustomPowerWatts([rl[1], wl[1], gl[1], bl[1]]);
    return {
      channels: { ...ch },
      pwm: [rl[0], wl[0], gl[0], bl[0], ch.fan],
      powerWatts,
    };
  };

  const rawEval = evaluate(req);
  if (!clampToMaxPower || rawEval.powerWatts <= profile.maxWatts) {
    return {
      modeCode: 12,
      gear: 0,
      pwm: rawEval.pwm,
      channels: rawEval.channels,
      requestedChannels: req,
      powerWatts: rawEval.powerWatts,
      maxWatts: profile.maxWatts,
      powerClamped: false,
    };
  }

  let lo = 0;
  let hi = 1;
  let best = evaluate({ red: 0, green: 0, white: 0, blue: 0, fan: req.fan });
  for (let iter = 0; iter < 18; iter += 1) {
    const mid = (lo + hi) / 2;
    const scaled = {
      red: Math.round(req.red * mid),
      green: Math.round(req.green * mid),
      white: Math.round(req.white * mid),
      blue: Math.round(req.blue * mid),
      fan: req.fan,
    };
    const cand = evaluate(scaled);
    if (cand.powerWatts <= profile.maxWatts) {
      best = cand;
      lo = mid;
    } else {
      hi = mid;
    }
  }

  return {
    modeCode: 12,
    gear: 0,
    pwm: best.pwm,
    channels: best.channels,
    requestedChannels: req,
    powerWatts: best.powerWatts,
    maxWatts: profile.maxWatts,
    powerClamped: true,
  };
}

/**
 * Normalize a 7-element weekday enable array `[Mon..Sun]` (length 7, values 0|1).
 * @param {unknown} raw
 * @returns {number[]}
 */
export function normalizeDayList(raw) {
  if (!Array.isArray(raw) || raw.length === 0) return [1, 1, 1, 1, 1, 1, 1];
  const out = [];
  for (let i = 0; i < 7; i += 1) {
    out.push(raw[i] ? 1 : 0);
  }
  return out;
}

/**
 * Compute per-day occupied half-open intervals `[start, end)` in minutes (handling overnight wrap).
 * @param {{ enable: number; dayList: number[]; startH: number; startM: number; endH: number; endM: number }} trip
 * @returns {Array<{ day: number; start: number; end: number; wrapsNextDay: boolean; fullDuration: number }>}
 */
function expandTripIntervals(trip) {
  const s = clampNum(trip.startH, 0, 23, 0) * 60 + clampNum(trip.startM, 0, 59, 0);
  const rawE = clampNum(trip.endH, 0, 23, 0) * 60 + clampNum(trip.endM, 0, 59, 0);
  const e = rawE === 0 && s > 0 ? 1440 : rawE;
  if (s === e) return [];
  const fullDuration = e > s ? e - s : (1440 - s + e);
  const out = [];
  for (let d = 0; d < 7; d += 1) {
    if (!trip.dayList[d]) continue;
    if (e > s) {
      out.push({ day: d, start: s, end: e, wrapsNextDay: false, fullDuration });
    } else {
      out.push({ day: d, start: s, end: 1440, wrapsNextDay: true, fullDuration });
      out.push({ day: (d + 1) % 7, start: 0, end: e, wrapsNextDay: false, fullDuration });
    }
  }
  return out;
}

/**
 * Validate `0..10` schedule trips for invalid times (`start == end`) or same-weekday overlaps,
 * and annotate sunrise/sunset flags matching Netlea's firmware logic (`getTravelRiChuRiLuo`).
 * @param {XproTrip[]} trips
 * @param {number} sunriseMinutes
 * @param {number} sunsetMinutes
 */
export function validateAndAnnotateTrips(trips, sunriseMinutes = 0, sunsetMinutes = 0) {
  if (!Array.isArray(trips)) {
    return { valid: false, error: '行程列表必须为数组', trips: [] };
  }
  if (trips.length > 10) {
    return { valid: false, error: '定时行程最多支持 10 个时段', trips: [] };
  }
  const rise = clampNum(sunriseMinutes, 0, 300, 0);
  const set = clampNum(sunsetMinutes, 0, 300, 0);

  /** @type {Array<Array<{ idx: number; start: number; end: number; fullDuration: number }>>} */
  const dayIntervals = Array.from({ length: 7 }, () => []);

  for (let i = 0; i < trips.length; i += 1) {
    const t = trips[i];
    const s = clampNum(t.startH, 0, 23, 0) * 60 + clampNum(t.startM, 0, 59, 0);
    const e = clampNum(t.endH, 0, 23, 0) * 60 + clampNum(t.endM, 0, 59, 0);
    if (s === e) {
      return { valid: false, error: `第 ${i + 1} 个时段开始时间与结束时间相同`, trips: [] };
    }
    if (!t.enable) continue;
    for (const seg of expandTripIntervals(t)) {
      dayIntervals[seg.day].push({ idx: i, start: seg.start, end: seg.end, fullDuration: seg.fullDuration });
    }
  }

  for (let d = 0; d < 7; d += 1) {
    const list = dayIntervals[d].sort((a, b) => a.start - b.start || a.end - b.end);
    for (let k = 1; k < list.length; k += 1) {
      const prev = list[k - 1];
      const cur = list[k];
      if (cur.start < prev.end) {
        const dayNames = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];
        return {
          valid: false,
          error: `${dayNames[d]}第 ${prev.idx + 1} 与第 ${cur.idx + 1} 个时段存在时间重叠`,
          trips: [],
        };
      }
    }
  }

  const annotated = trips.map((t, i) => {
    if (!t.enable || (rise === 0 && set === 0)) {
      return { ...t, hasSunrise: false, hasSunset: false, sunriseDays: [], sunsetDays: [] };
    }
    const s = clampNum(t.startH, 0, 23, 0) * 60 + clampNum(t.startM, 0, 59, 0);
    const rawE = clampNum(t.endH, 0, 23, 0) * 60 + clampNum(t.endM, 0, 59, 0);
    const e = rawE === 0 && s > 0 ? 1440 : rawE;
    const duration = e > s ? e - s : (1440 - s + e);

    const sunriseDays = [];
    const sunsetDays = [];
    for (let d = 0; d < 7; d += 1) {
      if (!t.dayList[d]) continue;
      // Check predecessor at `s` on day `d` (or end=1440 on prev day if s == 0)
      const hasPred = s === 0
        ? dayIntervals[(d + 6) % 7].some(x => x.idx !== i && x.end === 1440)
        : dayIntervals[d].some(x => x.idx !== i && x.end === s);
      // Check successor at `e` on day `d` (or start=0 on next day if e == 1440 / wraps)
      const endDay = e <= s ? (d + 1) % 7 : d;
      const endPoint = e === 1440 ? 0 : e;
      const checkDay = e === 1440 ? (d + 1) % 7 : endDay;
      const hasSucc = dayIntervals[checkDay].some(x => x.idx !== i && x.start === endPoint);

      let canRise = rise > 0 && !hasPred;
      let canSet = set > 0 && !hasSucc;
      if (canRise && canSet) {
        if (duration < rise + set) {
          if (duration >= rise) canSet = false;
          else if (duration < set) { canRise = false; canSet = false; }
          else { canRise = false; }
        }
      } else if (canRise && duration < rise) {
        canRise = false;
      } else if (canSet && duration < set) {
        canSet = false;
      }
      if (canRise) sunriseDays.push(d);
      if (canSet) sunsetDays.push(d);
    }

    return {
      ...t,
      hasSunrise: sunriseDays.length > 0,
      hasSunset: sunsetDays.length > 0,
      sunriseDays,
      sunsetDays,
    };
  });

  return { valid: true, error: '', trips: annotated };
}

/**
 * Normalize one user/UI trip object against the X-PRO profile (either official scene+gear or custom R/G/W/B).
 * @param {XproProfile} profile
 * @param {Record<string, unknown>} rawTrip
 * @returns {XproTrip}
 */
export function normalizeTripInput(profile, rawTrip) {
  const t = rawTrip && typeof rawTrip === 'object' ? rawTrip : {};
  const startH = clampNum(t.startH, 0, 23, 9);
  const startM = clampNum(t.startM, 0, 59, 0);
  const endH = clampNum(t.endH, 0, 23, 18);
  const endM = clampNum(t.endM, 0, 59, 0);
  const enable = t.enable === 0 || t.enable === false ? 0 : 1;
  const dayList = normalizeDayList(t.dayList);

  const reqMode = t.modeCode !== undefined ? Number(t.modeCode) : (t.id === 4 ? 12 : undefined);
  const hasExplicitChannels = t.red !== undefined || t.green !== undefined || t.white !== undefined || t.blue !== undefined;
  const isCustom = reqMode === 12 || (reqMode === undefined && hasExplicitChannels);

  if (!isCustom) {
    const encoded = encodeSceneGearPwm(
      profile,
      Number.isFinite(reqMode) ? reqMode : 0,
      t.gear !== undefined ? Number(t.gear) : 8,
      t.fan !== undefined ? Number(t.fan) : 0,
    );
    return {
      enable,
      dayList,
      startH,
      startM,
      endH,
      endM,
      modeCode: encoded.modeCode,
      gear: encoded.gear,
      red: encoded.channels.red,
      green: encoded.channels.green,
      white: encoded.channels.white,
      blue: encoded.channels.blue,
      fan: encoded.channels.fan,
      pwm: encoded.pwm,
      powerWatts: encoded.powerWatts,
      name: encoded.sceneName,
      seriesName: encoded.seriesName,
    };
  }

  const encoded = encodeCustomChannelsPwm(profile, {
    red: t.red,
    green: t.green,
    white: t.white,
    blue: t.blue,
    fan: t.fan,
  });
  return {
    enable,
    dayList,
    startH,
    startM,
    endH,
    endM,
    modeCode: 12,
    gear: 0,
    red: encoded.channels.red,
    green: encoded.channels.green,
    white: encoded.channels.white,
    blue: encoded.channels.blue,
    fan: encoded.channels.fan,
    pwm: encoded.pwm,
    powerWatts: encoded.powerWatts,
    name: '自定义',
    seriesName: '自定义',
  };
}

/**
 * Compute official cultivation preset multi-stage schedule (`opentankmodelConfig2traveList` in App v2.90).
 * @param {string} presetIdOrName
 * @param {Record<string, unknown>} [opts]
 * @param {XproProfile} [profile]
 */
export function buildPresetSchedule(presetIdOrName, opts = {}, profile = resolveXproProfile(DEFAULT_XPRO_MODEL)) {
  const key = String(presetIdOrName ?? '').trim();
  const preset = CULTIVATION_PRESETS.find(
    p => p.id === key || p.name === key || String(p.type) === key || p.name.replace('预设', '') === key,
  );
  if (!preset) {
    throw new Error(`未知的尼特利预设模式 "${presetIdOrName}"，可选：${CULTIVATION_PRESETS.map(p => `${p.id}(${p.name})`).join(', ')}`);
  }

  const lengthCm = clampNum(opts.lengthCm ?? opts.l, 10, 300, 60);
  const widthCm = clampNum(opts.widthCm ?? opts.w, 10, 200, 30);
  const rawHeight = clampNum(opts.heightCm ?? opts.h, 10, 200, 36);
  const steppedHeight = [30, 35, 40, 45, 50, 55, 60, 65, 70, 75].find(th => rawHeight <= th) ?? 80;
  const heightFactor = 0.8 + ((steppedHeight - 30) / 5) * 0.05;
  const lampCount = clampNum(opts.lampCount, 1, 8, 1);
  const baseWatts = (lengthCm * widthCm * heightFactor * 0.02) / lampCount;

  const startHour = clampNum(opts.startHour, 0, 23, 9);
  const startMinute = clampNum(opts.startMinute, 0, 59, 0);
  const sunriseMinutes = clampNum(opts.sunriseMinutes, 0, 300, 20);
  const sunsetMinutes = clampNum(opts.sunsetMinutes, 0, 300, 20);
  const dayList = normalizeDayList(opts.dayList);

  let curH = startHour;
  let curM = startMinute;
  /** @type {XproTrip[]} */
  const rawTrips = [];

  for (const st of preset.stages) {
    const targetWatts = Math.round(baseWatts * st.allPow);
    const modeCode = clampNum(st.colorModel - 1, 0, 3, 0);
    const scene = profile.scenes.find(s => s.modeCode === modeCode) || profile.scenes[0];
    let bestGear = 1;
    let bestDiff = Number.POSITIVE_INFINITY;
    for (let gi = 0; gi < scene.gears.length; gi += 1) {
      const diff = Math.abs(scene.gears[gi][4] - targetWatts);
      if (diff < bestDiff) {
        bestDiff = diff;
        bestGear = gi + 1;
      }
    }
    const encoded = encodeSceneGearPwm(profile, scene.modeCode, bestGear, 0);
    const totalEndMin = curH * 60 + curM + Math.round(st.hours * 60);
    const endH = Math.floor(totalEndMin / 60) % 24;
    const endM = totalEndMin % 60;

    rawTrips.push({
      enable: 1,
      dayList: [...dayList],
      startH: curH,
      startM: curM,
      endH,
      endM,
      modeCode: encoded.modeCode,
      gear: encoded.gear,
      red: encoded.channels.red,
      green: encoded.channels.green,
      white: encoded.channels.white,
      blue: encoded.channels.blue,
      fan: encoded.channels.fan,
      pwm: encoded.pwm,
      powerWatts: encoded.powerWatts,
      name: encoded.sceneName,
      seriesName: encoded.seriesName,
    });

    curH = endH;
    curM = endM;
  }

  const check = validateAndAnnotateTrips(rawTrips, sunriseMinutes, sunsetMinutes);
  return {
    presetId: preset.id,
    presetType: preset.type,
    presetName: preset.name,
    travelModel: 1,
    sunriseMinutes,
    sunsetMinutes,
    tankSize: { lengthCm, widthCm, heightCm: rawHeight, lampCount },
    targetBaseWatts: Math.round(baseWatts * 10) / 10,
    trips: check.valid ? check.trips : rawTrips,
  };
}

/**
 * Compact catalog summary exported in `dashboard` payload for the Web UI.
 * @param {XproProfile} profile
 */
export function buildCatalogSummary(profile) {
  return {
    modelKey: profile.key,
    maxWatts: profile.maxWatts,
    scenes: profile.scenes.map(s => ({
      modeCode: s.modeCode,
      model: s.model,
      seriesName: s.seriesName,
      tab: s.tab,
      name: s.name,
      maxGear: s.gears.length,
      gears: s.gears.map((g, idx) => {
        const d = decodeHardwarePwm(profile, [g[0], g[1], g[2], g[3], 0]);
        return {
          gear: idx + 1,
          powerWatts: g[4],
          pwm: [g[0], g[1], g[2], g[3], 0],
          channels: d.channels,
        };
      }),
    })),
    cultivationPresets: CULTIVATION_PRESETS.map(p => ({
      id: p.id,
      type: p.type,
      name: p.name,
      totalHours: p.stages.reduce((sum, s) => sum + s.hours, 0),
    })),
  };
}
